public class MemoryLeakExample {
    // This static reference acts as a GC Root, preventing reclamation
    private static List<Object> cache = new ArrayList<>();

    public void process() {
        Object obj = new Object();
        cache.add(obj); // Object is now reachable via the static 'cache' root
    }
    // Once 'cache' is cleared, the objects become unreachable and eligible for GC
}
